if (board[i][j] == '.') {
r = i;
c = j;
break;
}
}
if (r != -1) break;
}
if (r == -1) return true;
int b = (r / 3) * 3 + c / 3;
for (int num = 1; num <= 9; num++) {
int bit = 1 << num;
if ((row[r] & bit) || (col[c] & bit) || (box[b] & bit))
continue;
board[r][c] = char('0' + num);
row[r] |= bit;
col[c] |= bit;
box[b] |= bit;
if (solve(board, row, col, box))
return true;
board[r][c] = '.';
row[r] ^= bit;
col[c] ^= bit;
box[b] ^= bit;
}
return false;
}
