vector<string> solve(string& s, int start) {
if (start == s.size())
return {""};
if (memo.count(start))
return memo[start];
vector<string> ans;
string word;
for (int i = start; i < s.size(); i++) {
word += s[i];
if (!dict.count(word))
continue;
vector<string> suffix = solve(s, i + 1);
for (string& x : suffix) {
if (x.empty())
ans.push_back(word);
else
ans.push_back(word + " " + x);
}
}
return memo[start] = ans;
}
