// Core idea:
// DFS + low-link values identify biconnected components.
// Every biconnected component becomes a node.
// Every articulation vertex becomes another node.
// Connect an articulation vertex to every component containing it.

class DSU {
vector<int> parent, sz;
public:
DSU(int n) {
parent.resize(n);
sz.assign(n, 1);
iota(parent.begin(), parent.end(), 0);
}
int find(int x) {
if (parent[x] == x)
return x;
return parent[x] = find(parent[x]);
}
void unite(int a, int b) {
a = find(a);
b = find(b);
if (a == b)
return;
if (sz[a] < sz[b])
swap(a, b);
parent[b] = a;
sz[a] += sz[b];
}
bool connected(int a, int b) {
return find(a) == find(b);
}
};

