long long shortestWithDiscount(
int n,
vector<vector<pair<int,int>>>& adj,
int src,
int dest) {
const long long INF = 1e18;
vector<vector<long long>> dist(n,
vector<long long>(2, INF));
using T = tuple<long long,int,int>;
priority_queue<T, vector<T>, greater<T>> pq;
dist[src][0] = 0;
pq.push({0, src, 0});
while (!pq.empty()) {
auto [d, u, used] = pq.top();
pq.pop();
if (d != dist[u][used])
continue;
for (auto [v, w] : adj[u]) {
// Don't use discount.
if (d + w < dist[v][used]) {
dist[v][used] = d + w;
pq.push({dist[v][used], v, used});
}
// Use discount on this edge.
if (!used && d < dist[v][1]) {
dist[v][1] = d;
pq.push({d, v, 1});
}
}
}
return min(dist[dest][0], dist[dest][1]);
}

